  [22886] = { "敵に突進して吹き飛ばし、通常のダメージに加えて$N1のダメージを与えます。", nil, 0xa2823b6b, nil, "um" },
  [22887] = { "敵に武器を投げつけ、Physicalダメージを与えます。", nil, 0x6d14262e, nil, "um" },
  [22888] = { "呪文と攻撃のクリティカル率を$N1%、Attack Powerを$N2、呪文のダメージと回復量を最大$N3上げます。効果時間は$D1です。レイドインスタンス内では効果がありません。", "すべての呪文と攻撃のクリティカル率が$N1%、Attack Powerが$N2、呪文のダメージと回復量が最大$N3上昇します。レイドインスタンスでは効果がありません。", 0xf7cc3870, 0x5430e44b, "uu" },
  [22890] = { "Stun、Slowing、Immobilizingの効果を一つ取り除きます。", nil, 0x26ea35a5, nil, "um" },
  [22891] = { "Fear、Polymorph、Sleepの効果を一つ解除します。", nil, 0xfcb829b3, nil, "um" },
