  [22905] = { "Onyxiaの炎のブレスの下に置いてください。", nil, 0x89735e5c, nil, "um" },
  [22906] = { "熱した刃を鍛えるため、母竜の心臓に突き立ててください。", nil, 0xee536910, nil, "um" },
  [22907] = { "敵を撃ち、Physicalダメージを与えます。", nil, 0x75634826, nil, "um" },
  [22908] = { "対象範囲に弾薬の一斉射撃を浴びせ続け、$D1の間、毎秒$N2ヤード以内の敵の対象に$N1のArcaneダメージを与えます。", nil, 0x1e776398, nil, "um" },
  [22909] = { nil, "移動速度が$N1%低下しています。\n攻撃間隔が$N2%長くなっています。\n詠唱速度が$N3%低下しています。", nil, 0x80a44bb2, "mu" },
  [22910] = { "最初に近づいた敵を焼き、$D1かけて$N1のFireダメージを与える炎の罠を設置します。罠は$D2の間残ります。罠は戦闘中でないときにしか設置できません。同時に有効にできる罠は一つだけです。", nil, 0x6f5b9b69, nil, "um" },
  [22911] = { "敵に突撃し、通常ダメージ＋$N1のダメージを与え、$D1の間、相手をスタンさせます。", nil, 0xaf4293e6, nil, "um" },
  [22912] = { "盾のブロック値を$N1増加させます。", nil, 0xb2abc955, nil, "um" },
  [22914] = { "敵を朦朧とさせ、$D1の間、移動速度を$N1%低下させます。", "移動速度が$N1%低下しています。", 0xd6ffef29, 0x08fe36e7, "uu" },
  [22915] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
